(function(){'use strict';
const all=Array.from(document.querySelectorAll('.lean-change'));let active=null;
function position(w){const b=w.querySelector('.lean-change-toggle'),p=w.querySelector('.lean-change-popover'),r=b.getBoundingClientRect();const vw=window.innerWidth||document.documentElement.clientWidth,vh=window.innerHeight||document.documentElement.clientHeight;p.style.left=Math.max(12,Math.min(r.left,vw-p.offsetWidth-12))+'px';const h=p.offsetHeight;let top=r.bottom+6;if(top+h>vh-12)top=Math.max(12,r.top-h-6);p.style.top=top+'px';}
function close(w,restore){if(!w)return;clearTimeout(w._leanTimer);w._leanPinned=false;w.querySelector('.lean-change-popover').hidden=true;w.querySelector('.lean-change-toggle').setAttribute('aria-expanded','false');if(active===w)active=null;if(restore){w._leanSuppress=true;w.querySelector('.lean-change-toggle').focus();w._leanSuppress=false;}}
function open(w){clearTimeout(w._leanTimer);if(active&&active!==w)close(active,false);active=w;w.querySelector('.lean-change-popover').hidden=false;w.querySelector('.lean-change-toggle').setAttribute('aria-expanded','true');position(w);}
all.forEach(w=>{const b=w.querySelector('.lean-change-toggle'),p=w.querySelector('.lean-change-popover');b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(w._leanPinned)close(w,false);else{open(w);w._leanPinned=true;}});w.addEventListener('mouseenter',()=>open(w));w.addEventListener('mouseleave',()=>{if(!w._leanPinned)w._leanTimer=setTimeout(()=>{if(!w.contains(document.activeElement))close(w,false);},160);});w.addEventListener('focusin',()=>{if(!w._leanSuppress)open(w);});w.addEventListener('focusout',e=>{if(!w.contains(e.relatedTarget)&&!w._leanPinned)close(w,false);});p.querySelector('.lean-change-close').addEventListener('click',e=>{e.preventDefault();e.stopPropagation();close(w,true);});w.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close(w,true);}});});
document.addEventListener('keydown',e=>{if(active&&e.key==='Escape'){e.preventDefault();close(active,true);}});
document.addEventListener('click',e=>{if(active&&!active.contains(e.target))close(active,false);});window.addEventListener('resize',()=>{if(active)position(active);});window.addEventListener('scroll',()=>{if(active)position(active);},{passive:true});
})();
